/// <summary>
/// The service class for the Planner code update batch job.
/// </summary>
class METPlannerCodeUpdService extends SysOperationServiceBase
{
    METPlannerCodeUpdateTmp                     metPlannerCodeUpdateTmp;
    METPlannerCodeUpdateBridgeTmp               metPlannerCodeUpdateBridgeTmp;
    METPlannerCodeUpdateBridgeLastModifiedTmp   metPlannerCodeUpdateBridgeLastModifiedTmp;

}

Method.Source:
    /// <summary>
    /// The process method of the planner code update batch job
    /// </summary>
    public void processOperation()
    {
        #OCCRetryCount
        METPlannerCodeAssignmentRules   metPlannerCodeAssignmentRulesUpdate;
        METPlannerCodeAssignmentRules   metPlannerCodeAssignmentRulesReset;

        //Empty temp tables.
        delete_from metPlannerCodeUpdateTmp;
        delete_from metPlannerCodeUpdateBridgeTmp;
        delete_from metPlannerCodeUpdateBridgeLastModifiedTmp;

        // Insert all item coverage records in temp table
        this.insertItemCoverageRecords();
        
        // Update Planner code in temp table according to weight
        this.updateWeight6();
        this.updateWeight5();
        this.updateWeight4();
        this.updateWeight3();
        this.updateWeight2();
        this.updateWeight1();
        
        try
        {
            ttsbegin;

            // Reset all last used rules
            metPlannerCodeAssignmentRulesReset.skipDataMethods(true);
            metPlannerCodeAssignmentRulesReset.skipDatabaseLog(true);
            metPlannerCodeAssignmentRulesReset.skipAosValidation(true);

            update_recordset metPlannerCodeAssignmentRulesReset
                setting RuleUsedBatchUpdate = NoYes::No
                where metPlannerCodeAssignmentRulesReset.RuleEnabled == NoYes::Yes;

            // Update item coverage records from temp table.
            this.updateItemCoverageRecords();

            // Set last rules used to true
            metPlannerCodeAssignmentRulesUpdate.skipDataMethods(true);
            metPlannerCodeAssignmentRulesUpdate.skipDatabaseLog(true);
            metPlannerCodeAssignmentRulesUpdate.skipAosValidation(true);

            // Mark last used rules to true
            update_recordset metPlannerCodeAssignmentRulesUpdate
                setting RuleUsedBatchUpdate = NoYes::Yes
            join PlannerRecId from metPlannerCodeUpdateTmp
                where metPlannerCodeAssignmentRulesUpdate.RecId == metPlannerCodeUpdateTmp.PlannerRecId;

            //Empty the temp table.
            delete_from metPlannerCodeUpdateTmp;

            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }

    /// <summary>
    /// Inserts the item coverage records in the temp table
    /// </summary>
    private void insertItemCoverageRecords()
    {
        ReqItemTable                    reqItemTable;
        METReqItemTable                 metreqItemTable;
        InventDim                       inventDim;
        InventTable                     inventTable;
        EcoResProductCategory           ecoResProductCategory;
        InventItemGroupItem             inventItemGroupItem;
       
        insert_recordset metPlannerCodeUpdateTmp (ItemId, CovInventDimId, VendorAccount, RuleSubSource, InventSiteId, InventLocationId, ItemGroup, ProductCategoryHierarchy, ProductCategory)
        select ItemId, CovInventDimId, VendId from reqItemTable
            join SubSource from metreqItemTable
                where metreqItemTable.RefRecId == reqItemTable.RecId
            join InventSiteId, InventLocationId from inventDim
                where inventDim.inventDimId == reqItemTable.CovInventDimId
            join inventTable
                where inventTable.ItemId == reqItemTable.ItemId
            join ItemGroupId from inventItemGroupItem
                where inventItemGroupItem.ItemId == inventTable.ItemId
                && inventItemGroupItem.ItemDataAreaId   == curExt()
            join CategoryHierarchy, Category from ecoResProductCategory
                where ecoResProductCategory.Product == inventTable.Product;

    }

    /// <summary>
    /// Updates the Item coverage records from temp to permanent table
    /// </summary>
    private void updateItemCoverageRecords()
    {
        METReqItemTable metReqItemTable;
        ReqItemTable    reqItemTable;

        delete_from metPlannerCodeUpdateTmp
            where metPlannerCodeUpdateTmp.PlannerRecId == 0;

        metReqItemTable.skipDataMethods(true);
        metReqItemTable.skipDatabaseLog(true);
        metReqItemTable.skipAosValidation(true);

        update_recordset metreqItemTable
            setting Planner = metPlannerCodeUpdateTmp.PlannerCode
            join RecId from reqItemTable
                where reqItemTable.RecId == metreqItemTable.RefRecId
            join PlannerCode from metPlannerCodeUpdateTmp
                where metPlannerCodeUpdateTmp.ItemId == reqItemTable.ItemId
                && metPlannerCodeUpdateTmp.CovInventDimId == reqItemTable.CovInventDimId;
    }

    /// <summary>
    /// Updates the temp tables with correct planner code data
    /// </summary>
    private void updateTmpTable()
    {
        insert_recordset metPlannerCodeUpdateBridgeLastModifiedTmp (ItemId, CovInventDimId, RuleSubSource, RuleModifiedDateTime)
            select ItemId, CovInventDimId, RuleSubSource, maxof(RuleModifiedDateTime)
            from metPlannerCodeUpdateBridgeTmp
            group by ItemId, CovInventDimId, RuleSubSource;

        update_recordset metPlannerCodeUpdateBridgeLastModifiedTmp
            setting PlannerCode = metPlannerCodeUpdateBridgeTmp.PlannerCode, PlannerRecId = metPlannerCodeUpdateBridgeTmp.PlannerRecId
        join metPlannerCodeUpdateBridgeTmp
            where metPlannerCodeUpdateBridgeTmp.ItemId == metPlannerCodeUpdateBridgeLastModifiedTmp.ItemId
            && metPlannerCodeUpdateBridgeTmp.CovInventDimId == metPlannerCodeUpdateBridgeLastModifiedTmp.CovInventDimId
            && metPlannerCodeUpdateBridgeTmp.RuleSubSource == metPlannerCodeUpdateBridgeLastModifiedTmp.RuleSubSource
            && metPlannerCodeUpdateBridgeTmp.RuleModifiedDateTime == metPlannerCodeUpdateBridgeLastModifiedTmp.RuleModifiedDateTime;

        update_recordset metPlannerCodeUpdateTmp
            setting PlannerCode = metPlannerCodeUpdateBridgeLastModifiedTmp.PlannerCode, PlannerRecId = metPlannerCodeUpdateBridgeLastModifiedTmp.PlannerRecId
            where metPlannerCodeUpdateTmp.PlannerCode == ''
        join metPlannerCodeUpdateBridgeLastModifiedTmp
            where metPlannerCodeUpdateBridgeLastModifiedTmp.ItemId == metPlannerCodeUpdateTmp.ItemId
            && metPlannerCodeUpdateBridgeLastModifiedTmp.CovInventDimId == metPlannerCodeUpdateTmp.CovInventDimId
            && metPlannerCodeUpdateBridgeLastModifiedTmp.RuleSubSource == metPlannerCodeUpdateTmp.RuleSubSource;

        delete_from metPlannerCodeUpdateBridgeTmp;
        delete_from metPlannerCodeUpdateBridgeLastModifiedTmp;

    }

    /// <summary>
    /// Populates temp table with records having weight = 6
    /// </summary>
    private void updateWeight6()
    {
        METPlannerCodeAssignmentRules   metPlannerCodeAssignmentRules;
        METPlannerCodeUpdateBridgeTmp   metPlannerCodeUpdateBridgeTmpExist;

        // Exact match
        insert_recordset metPlannerCodeUpdateBridgeTmp (ItemId, CovInventDimId, RuleSubSource, PlannerCode, PlannerRecId, RuleModifiedDateTime)
            select ItemId, CovInventDimId, RuleSubSource from metPlannerCodeUpdateTmp
                where metPlannerCodeUpdateTmp.PlannerRecId == 0
            join PlannerCode, RecId, RuleEnabledStatusLastModified from metPlannerCodeAssignmentRules
                where metPlannerCodeAssignmentRules.RuleSubSource == metPlannerCodeUpdateTmp.RuleSubSource
                && metPlannerCodeAssignmentRules.RuleEnabled == NoYes::Yes

                && metPlannerCodeAssignmentRules.RuleVendorWarehouse == metPlannerCodeUpdateTmp.InventLocationId
                && metPlannerCodeUpdateTmp.InventSiteId == metPlannerCodeAssignmentRules.RuleVendorSite
                && metPlannerCodeUpdateTmp.ItemGroup == metPlannerCodeAssignmentRules.RuleItemGroup
                && metPlannerCodeUpdateTmp.ProductCategory ==  metPlannerCodeAssignmentRules.RuleProductCategory
                && metPlannerCodeUpdateTmp.ProductCategoryHierarchy == metPlannerCodeAssignmentRules.RuleProductCategoryHierarchy
                && metPlannerCodeUpdateTmp.VendorAccount == metPlannerCodeAssignmentRules.RuleVendorAccount;

        metPlannerCodeUpdateBridgeTmpExist.linkPhysicalTableInstance(metPlannerCodeUpdateBridgeTmp);

        // Blank Warehouse
        insert_recordset metPlannerCodeUpdateBridgeTmp (ItemId, CovInventDimId, RuleSubSource, PlannerCode, PlannerRecId, RuleModifiedDateTime)
            select ItemId, CovInventDimId, RuleSubSource from metPlannerCodeUpdateTmp
                where metPlannerCodeUpdateTmp.PlannerRecId == 0
            join PlannerCode, RecId, RuleEnabledStatusLastModified from metPlannerCodeAssignmentRules
                where metPlannerCodeAssignmentRules.RuleSubSource == metPlannerCodeUpdateTmp.RuleSubSource
                && metPlannerCodeAssignmentRules.RuleEnabled == NoYes::Yes
                && metPlannerCodeAssignmentRules.RuleVendorWarehouse == ''

                && metPlannerCodeUpdateTmp.InventSiteId == metPlannerCodeAssignmentRules.RuleVendorSite
                && metPlannerCodeUpdateTmp.ItemGroup == metPlannerCodeAssignmentRules.RuleItemGroup
                && metPlannerCodeUpdateTmp.ProductCategory ==  metPlannerCodeAssignmentRules.RuleProductCategory
                && metPlannerCodeUpdateTmp.ProductCategoryHierarchy == metPlannerCodeAssignmentRules.RuleProductCategoryHierarchy
                && metPlannerCodeUpdateTmp.VendorAccount == metPlannerCodeAssignmentRules.RuleVendorAccount
            notexists join metPlannerCodeUpdateBridgeTmpExist
            where metPlannerCodeUpdateBridgeTmpExist.ItemId             == metPlannerCodeUpdateTmp.ItemId
                && metPlannerCodeUpdateBridgeTmpExist.CovInventDimId    == metPlannerCodeUpdateTmp.CovInventDimId
                && metPlannerCodeUpdateBridgeTmpExist.RuleSubSource     == metPlannerCodeUpdateTmp.RuleSubSource;

        this.updateTmpTable();
        
    }

